    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // 3. Register nodes
    graph.addNode(sensor1);
    graph.addNode(sensor2);
    graph.addNode(observer);

    // 4. Set up initial dependency (observer observes sensor1)
    graph.addObserver(observer, sensor1);

    // 5. Save node state for rollback
    auto rollback = graph.saveNodeStateForRollback(observer);

    // 6. Replace dependencies transactionally (observer now observes sensor2)
    graph.updateObserversTransactional(observer, sensor2);

    // 7. Trigger notification on second sensor
    sensor2->notify();

    // 8. Record notification count after second binding
    int notificationsAfterSecondBinding = observer->notificationCount();

    // 9. Execute rollback
    rollback();

    // 10. Trigger notification on first sensor
    sensor1->notify();

    // 11. Record notification count after rollback
    int notificationsAfterRollback = observer->notificationCount();

    // 12. Return notification counts
    return RollbackObservation{
        notificationsAfterSecondBinding,
        notificationsAfterRollback
    };
}

