    void triggerCleanup() noexcept {
        triggerCleanupInternal();
    }

private:
    static constexpr size_t MAX_CYCLE_CACHE_SIZE = 1000;
    static constexpr std::chrono::minutes CACHE_TTL{10};
};

/**
