            });
            this->setSource(std::forward<F>(f));
        }
        this->notify();
    }

    /// @brief Set a no-argument expression and auto-track dependencies.
    void set() {
        RegFunGuard g([this](const NodePtr &node) {
            this->addObCb(node);
        });
        this->setOpExpr();
    }

