        return m_id;
    }

private:
    uint64_t m_id; ///< Internal unique identifier.

    /**
     * @brief Static function to generate a unique 64-bit ID.
     * @return A unique 64-bit unsigned integer.
     */
    static uint64_t generate() noexcept {
        static uint64_t counter{0};
        return counter++;
